CREATE TABLE CustomerDetails (
    customer_id INT,
    name VARCHAR(100),
    city VARCHAR(100),
    total_spent DECIMAL(10,2)
)WITH
(
    DISTRIBUTION = ROUND_ROBIN,
    CLUSTERED COLUMNSTORE INDEX
);

SELECT * FROM CustomerDetails;

